import pytest

from bedrock_protocol import nbt, v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# packet.AvailableActorIdentifiers{SerialisedEntityIdentifiers:
# nbt.MarshalEncoding(identifierList{IDList: []actorInfo{{ID: "minecraft:pig", RID: 200}}}, nbt.NetworkLittleEndian)}
PIG = bytes.fromhex("0a00090669646c6973740a02080269640d6d696e6563726166743a706967030372696490030000")

# generated by gophertunnel b8bd735:
# packet.AvailableActorIdentifiers{SerialisedEntityIdentifiers:
# nbt.MarshalEncoding(map[string]any{}, nbt.NetworkLittleEndian)}
EMPTY_TAG = bytes.fromhex("0a0000")

GOLDENS = [
    pytest.param(
        v2225.AvailableActorIdentifiersPacket(
            identifier_list=nbt.CompoundTag(
                {
                    "idlist": nbt.ListTag(
                        [nbt.CompoundTag({"id": nbt.StringTag("minecraft:pig"), "rid": nbt.IntTag(200)})]
                    )
                }
            )
        ),
        PIG,
        id="pig",
    ),
    pytest.param(v2225.AvailableActorIdentifiersPacket(), EMPTY_TAG, id="empty-tag"),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_available_actor_identifiers_is_packet_119(version):
    assert version.packets[119] is version.AvailableActorIdentifiersPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_available_actor_identifiers_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_available_actor_identifiers_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
